#include "s61_binary_deeper_cubic_field_20261101.hpp"
using namespace cubic_field;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[2];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1];flint_free(s);}o<<'\n';fmpq_clear(q);}
struct Matrix{int n,m;vector<Poly>den;vector<vector<Poly>>row;Poly common;};
Matrix readmatrix(istream&in){Matrix A;in>>A.n>>A.m;A.den.resize(A.n);A.row.resize(A.n,vector<Poly>(A.m));fmpq_mpoly_one(A.common.p,ctx);Poly g,q,t;for(int i=0;i<A.n;i++){read_poly(in,A.den[i].p);assert(!fmpq_mpoly_is_zero(A.den[i].p,ctx));for(auto&v:A.row[i])read_poly(in,v.p);assert(fmpq_mpoly_gcd(g.p,A.common.p,A.den[i].p,ctx));assert(fmpq_mpoly_divides(q.p,A.den[i].p,g.p,ctx));fmpq_mpoly_mul(t.p,A.common.p,q.p,ctx);fmpq_mpoly_make_monic(A.common.p,t.p,ctx);}return A;}
void outputmatrix(ostream&out,const Matrix&A){out<<A.n<<' '<<A.m<<'\n';Poly mult,t;for(int i=0;i<A.n;i++){assert(fmpq_mpoly_divides(mult.p,A.common.p,A.den[i].p,ctx));for(auto&v:A.row[i]){fmpq_mpoly_mul(t.p,v.p,mult.p,ctx);write(out,t);}}}
int main(int argc,char**argv){assert(argc==3);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]);ofstream out(argv[2]);assert(in&&out);Poly DQ;read_poly(in,DQ.p);vector<int>qp(132);for(int&i:qp)in>>i;vector<map<int,string>>B(238);for(auto&r:B){int n;in>>n;for(int k=0;k<n;k++){int j;string c;in>>j>>c;r[j]=c;}}
Matrix A1=readmatrix(in),A2=readmatrix(in),T=readmatrix(in),Ref=readmatrix(in);assert(A1.n==189&&A1.m==238&&A2.n==189&&A2.m==106&&T.n==132&&T.m==106&&Ref.n==147&&Ref.m==106);
fmpq_t c;fmpq_init(c);Poly tmp,lhs,rhs;for(int i=0;i<147;i++){vector<Poly>pr(106);for(int j=0;j<238;j++)for(auto&[k,cs]:B[j]){assert(fmpq_set_str(c,cs.c_str(),10)==0);fmpq_canonicalise(c);fmpq_mpoly_scalar_mul_fmpq(tmp.p,A1.row[i+42][j].p,c,ctx);fmpq_mpoly_add(pr[k].p,pr[k].p,tmp.p,ctx);}for(int k=0;k<106;k++){fmpq_mpoly_mul(lhs.p,pr[k].p,Ref.den[i].p,ctx);fmpq_mpoly_mul(rhs.p,Ref.row[i][k].p,A1.den[i+42].p,ctx);assert(fmpq_mpoly_equal(lhs.p,rhs.p,ctx));}}
fmpq_clear(c);assert(fmpq_mpoly_equal(T.common.p,DQ.p,ctx));write(out,A1.common);write(out,A2.common);write(out,DQ);for(int q:qp)out<<q<<' ';out<<'\n';for(auto&r:B){out<<r.size();for(auto&[j,c]:r)out<<' '<<j<<' '<<c;out<<'\n';}outputmatrix(out,A1);outputmatrix(out,A2);outputmatrix(out,T);cerr<<"PASS full/projected first equality 147x106 and all exact common-denominator quotients\n";}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
